"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand_lines(lines, path, stack):
    """Return ``lines`` (read from ``path``) with ``@include`` expanded."""
    base = os.path.dirname(path)
    out = []
    for raw in lines:
        parts = raw.split(None, 1)
        if not parts or parts[0] != INCLUDE_DIRECTIVE:
            out.append(raw)
            continue
        target = parts[1].strip() if len(parts) > 1 else ""
        if not target:
            raise ConfigError("{}: @include requires a path".format(path))
        child = os.path.join(base, target)
        real = os.path.realpath(child)
        if real in stack:
            chain = " -> ".join(stack + [real])
            raise ConfigError("include cycle detected: {}".format(chain))
        try:
            child_lines = _read_lines(child)
        except FileNotFoundError:
            raise ConfigError(
                "{}: include file not found: {}".format(path, child)
            ) from None
        out.extend(_expand_lines(child_lines, child, stack + [real]))
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are expanded in place with the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    expanded = _expand_lines(lines, path, [os.path.realpath(path)])
    return parse_lines(expanded)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
